#!/usr/bin/env python3
"""Add missing RTLIB enum values that are referenced without RTLIB:: prefix."""

import os

LLVM_KAIN = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INC_PATH = os.path.join(LLVM_KAIN, "include", "core", "ir", "RuntimeLibcalls.inc")

# Missing values that are generated by .td multiclass expansion
# but used without RTLIB:: prefix in source files

missing_libcall = set()

# OUTLINE_ATOMIC_CAS/SWP/LDADD/LDSET/LDCLR/LDEOR with MemSize 1,2,4,8,16 and orders RELAX/ACQ/REL/ACQ_REL
for prefix in ["OUTLINE_ATOMIC_CAS", "OUTLINE_ATOMIC_SWP", "OUTLINE_ATOMIC_LDADD",
                "OUTLINE_ATOMIC_LDSET", "OUTLINE_ATOMIC_LDCLR", "OUTLINE_ATOMIC_LDEOR"]:
    for size in [1, 2, 4, 8, 16]:
        for order in ["RELAX", "ACQ", "REL", "ACQ_REL"]:
            missing_libcall.add(f"{prefix}{size}_{order}")

# POWI variants: from foreach FPTy = ["F32","F64","F80","F128","PPCF128"]
for fpty in ["F32", "F64", "F80", "F128", "PPCF128"]:
    missing_libcall.add(f"POWI_{fpty}")

# SINCOS variants
for fpty in ["F32", "F64", "F80", "F128", "PPCF128"]:
    missing_libcall.add(f"SINCOS_{fpty}")

# SINCOS_STRET variants (F32, F64 only)
for fpty in ["F32", "F64"]:
    missing_libcall.add(f"SINCOS_STRET_{fpty}")

# MODF variants
for fpty in ["F32", "F64", "F80", "F128", "PPCF128"]:
    missing_libcall.add(f"MODF_{fpty}")

# FREXP variants
for fpty in ["F32", "F64", "F80", "F128", "PPCF128"]:
    missing_libcall.add(f"FREXP_{fpty}")

# LDEXP variants
for fpty in ["F32", "F64", "F80", "F128", "PPCF128"]:
    missing_libcall.add(f"LDEXP_{fpty}")

# Read existing file
with open(INC_PATH, "r") as f:
    content = f.read()

# Find existing symbols
existing = set()
for line in content.split("\n"):
    stripped = line.strip()
    if stripped.endswith(",") and not stripped.startswith("//") and not stripped.startswith("#"):
        symbol = stripped.rstrip(",").strip()
        if symbol and symbol[0].isupper():
            existing.add(symbol)

# Filter to truly missing
to_add = sorted(missing_libcall - existing)
print(f"Existing symbols: {len(existing)}")
print(f"Missing to add: {len(to_add)}")

if not to_add:
    print("Nothing to add!")
else:
    # Insert before NumLibcallIds line
    insert_pos = content.find("  NumLibcallIds")
    insert_lines = "\n".join(f"  {s}," for s in to_add)
    
    # Count current symbols (existing - UNKNOWN_LIBCALL - NumLibcallIds)
    current_count = int([l for l in content.split("\n") if "NumLibcallIds" in l][0].split("=")[1].strip())
    new_count = current_count + len(to_add)
    
    # Build new content
    before = content[:insert_pos]
    after = content[insert_pos:]
    after = after.replace(f"NumLibcallIds = {current_count}", f"NumLibcallIds = {new_count}")
    
    new_content = before + insert_lines + "\n" + after
    
    with open(INC_PATH, "w") as f:
        f.write(new_content)
    
    print(f"Added {len(to_add)} symbols to RuntimeLibcalls.inc")
    print(f"NumLibcallIds updated from {current_count} to {new_count}")
